//! The bundled self-manual: static text about this harness, compiled in from
//! `assets/self/MANUAL.md` (generated by `scripts/build-self-manual.py`),
//! chunked on `## ` headings and indexed once at startup in a Tantivy RAM
//! index. Local chat turns and `/prompt` get the best-matching chunks as
//! untrusted background. It reads nothing from the home, never shares the
//! public web index and is never persisted.

use tantivy::collector::TopDocs;
use tantivy::query::QueryParser;
use tantivy::schema::{
    Field, IndexRecordOption, Schema, TantivyDocument, TextFieldIndexing, TextOptions, Value as _, STORED,
};
use tantivy::{doc, Index, IndexReader};

use crate::common::config::AppConfig;
use crate::common::errors::{HarnessError, Result};

pub const MANUAL: &str = include_str!("../../assets/self/MANUAL.md");
/// Longest slice of the user message used as a query; terms are clipped to 32.
const MAX_QUERY_CHARS: usize = 512;
const CANDIDATES: usize = 16;

/// The `diagnostics` self-knowledge settings. Restart-only.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct SelfKnowledgeConfig {
    pub self_knowledge: bool,
    pub max_chunks: usize,
    pub max_chars: usize,
    pub min_score: f32,
    pub live_state: bool,
}

impl SelfKnowledgeConfig {
    /// `self_knowledge` and `live_state` are not `flag_is_true` gates: a
    /// missing key is on, a literal boolean is used as written, and any other
    /// value fails boot (so quoted `"true"` cannot pass as either). Ranges are hard.
    pub fn from_config(cfg: &AppConfig) -> Result<Self> {
        if cfg.get("diagnostics").is_some_and(|v| !v.is_mapping() && !v.is_null()) {
            return Err(HarnessError::config("diagnostics must be a mapping"));
        }
        let max_chunks = bounded(cfg, "diagnostics.self_manual_max_chunks", 4, 1, 8)? as usize;
        let max_chars = bounded(cfg, "diagnostics.self_manual_max_chars", 6000, 512, 16_000)? as usize;
        let min_score = match cfg.get("diagnostics.self_manual_min_score") {
            None => 0.0,
            Some(v) => v
                .as_f64()
                .filter(|n| n.is_finite() && *n >= 0.0 && *n <= f32::MAX as f64)
                .ok_or_else(|| HarnessError::config("diagnostics.self_manual_min_score must be a finite number >= 0"))?
                as f32,
        };
        Ok(Self {
            self_knowledge: missing_on(cfg, "diagnostics.self_knowledge")?,
            max_chunks,
            max_chars,
            min_score,
            live_state: missing_on(cfg, "diagnostics.live_state")?,
        })
    }
}

fn missing_on(cfg: &AppConfig, key: &str) -> Result<bool> {
    match cfg.get(key) {
        None => Ok(true),
        Some(serde_yaml_ng::Value::Bool(b)) => Ok(*b),
        Some(_) => Err(HarnessError::config(format!("{key} must be a literal YAML boolean"))),
    }
}

fn bounded(cfg: &AppConfig, key: &str, default: u64, min: u64, max: u64) -> Result<u64> {
    match cfg.get(key) {
        None => Ok(default),
        Some(v) => v
            .as_u64()
            .filter(|n| (min..=max).contains(n))
            .ok_or_else(|| HarnessError::config(format!("{key} must be an integer from {min} to {max}"))),
    }
}

/// One `## ` chunk of the manual. `id` is `m01`, `m02`, ... in file order.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Chunk {
    pub id: String,
    pub title: String,
    pub text: String,
}

/// Chunks of `manual` in file order; the generator header is skipped.
pub fn parse_chunks(manual: &str) -> Vec<Chunk> {
    let mut out = Vec::new();
    for block in manual.split("\n## ").skip(1) {
        let (title, body) = block.split_once('\n').unwrap_or((block, ""));
        out.push(Chunk {
            id: format!("m{:02}", out.len() + 1),
            title: title.trim().to_string(),
            text: body.trim().to_string(),
        });
    }
    out
}

/// What one turn carries: chunk ids, the fenced body and its size.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Selection {
    pub ids: Vec<String>,
    pub chars: usize,
    pub block: String,
}

pub struct SelfManual {
    pub chunks: Vec<Chunk>,
    pub sha256: String,
    index: Index,
    reader: IndexReader,
    f_title: Field,
    f_body: Field,
    f_row: Field,
}

impl SelfManual {
    pub fn build(manual: &str) -> Result<Self> {
        let failed = |_| HarnessError::new("SELF_MANUAL_INDEX", "could not index the bundled manual");
        let mut builder = Schema::builder();
        let text = TextOptions::default().set_indexing_options(
            TextFieldIndexing::default()
                .set_tokenizer("en_stem")
                .set_index_option(IndexRecordOption::WithFreqsAndPositions),
        );
        let f_title = builder.add_text_field("title", text.clone());
        let f_body = builder.add_text_field("text", text);
        let f_row = builder.add_u64_field("row", STORED);
        let index = Index::create_in_ram(builder.build());
        let chunks = parse_chunks(manual);
        let mut writer = index.writer_with_num_threads(1, 15_000_000).map_err(failed)?;
        for (row, chunk) in chunks.iter().enumerate() {
            writer
                .add_document(doc!(f_title => chunk.title.as_str(), f_body => chunk.text.as_str(), f_row => row as u64))
                .map_err(failed)?;
        }
        writer.commit().map_err(failed)?;
        let reader = index.reader().map_err(failed)?;
        Ok(Self {
            chunks,
            sha256: crate::common::sha256_hex(manual),
            index,
            reader,
            f_title,
            f_body,
            f_row,
        })
    }

    /// The best chunks for `message` above `min_score`, at most `max_chunks`
    /// whole chunks within `max_chars` (a first chunk longer than that is
    /// clipped). `None` when nothing matches.
    pub fn select(&self, message: &str, cfg: &SelfKnowledgeConfig) -> Option<Selection> {
        let query = crate::common::clip_chars(message.trim(), MAX_QUERY_CHARS);
        let expression = super::retrieval_ranking::tantivy_expression(&query)?;
        let parser = QueryParser::for_index(&self.index, vec![self.f_title, self.f_body]);
        let parsed = parser.parse_query_lenient(&expression).0;
        let searcher = self.reader.searcher();
        let top = searcher
            .search(&parsed, &TopDocs::with_limit(CANDIDATES).order_by_score())
            .ok()?;
        let mut ids = Vec::new();
        let mut sections: Vec<String> = Vec::new();
        let mut used = 0usize;
        for (score, address) in top {
            if score < cfg.min_score || ids.len() >= cfg.max_chunks {
                break;
            }
            let Ok(document) = searcher.doc::<TantivyDocument>(address) else {
                continue;
            };
            let Some(row) = document.get_first(self.f_row).and_then(|v| v.as_u64()) else {
                continue;
            };
            let chunk = &self.chunks[row as usize];
            let mut section = format!(
                "### self_manual {} ({}), source=self_manual\n{}",
                chunk.id, chunk.title, chunk.text
            );
            let size = section.chars().count();
            if used + size > cfg.max_chars {
                if !sections.is_empty() {
                    break;
                }
                section = crate::common::clip_chars(&section, cfg.max_chars);
            }
            used += section.chars().count();
            ids.push(chunk.id.clone());
            sections.push(section);
        }
        if ids.is_empty() {
            return None;
        }
        let body = sections.join("\n\n");
        let block = format!(
            "self_manual: {} chunks, {} chars, sha256 {}\n{body}",
            ids.len(),
            body.chars().count(),
            self.sha256
        );
        Some(Selection {
            ids,
            chars: body.chars().count(),
            block,
        })
    }
}

/// Startup state: the settings plus the index when `self_knowledge` is on.
pub struct SelfKnowledge {
    pub config: SelfKnowledgeConfig,
    pub manual: Option<SelfManual>,
}

impl SelfKnowledge {
    pub fn new(cfg: &AppConfig) -> Result<Self> {
        let config = SelfKnowledgeConfig::from_config(cfg)?;
        let manual = if config.self_knowledge {
            Some(SelfManual::build(MANUAL)?)
        } else {
            None
        };
        Ok(Self { config, manual })
    }

    /// Chunks for one local chat turn or preview; callers never ask for cloud,
    /// `/loop` or `/agent`.
    pub fn select(&self, message: &str) -> Option<Selection> {
        self.manual.as_ref()?.select(message, &self.config)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::Path;

    fn cfg(yaml: &str) -> Result<SelfKnowledgeConfig> {
        SelfKnowledgeConfig::from_config(&AppConfig::from_str(yaml, Path::new("c.yaml")).unwrap())
    }

    #[test]
    fn switches_are_on_when_missing_literal_when_set_and_refuse_anything_else() {
        let shipped = cfg(AppConfig::embedded_default()).unwrap();
        assert!(shipped.self_knowledge && shipped.live_state);
        assert_eq!(
            (shipped.max_chunks, shipped.max_chars, shipped.min_score),
            (4, 6000, 0.0)
        );
        let missing = cfg("{}\n").unwrap();
        assert!(missing.self_knowledge && missing.live_state);
        let off = cfg("diagnostics:\n  self_knowledge: false\n  live_state: false\n").unwrap();
        assert!(!off.self_knowledge && !off.live_state);
        for bad in [
            "diagnostics:\n  self_knowledge: \"true\"\n",
            "diagnostics:\n  live_state: \"false\"\n",
            "diagnostics:\n  self_knowledge: 1\n",
            "diagnostics:\n  self_manual_max_chunks: 0\n",
            "diagnostics:\n  self_manual_max_chunks: 9\n",
            "diagnostics:\n  self_manual_max_chars: 511\n",
            "diagnostics:\n  self_manual_max_chars: 16001\n",
            "diagnostics:\n  self_manual_min_score: -1\n",
            "diagnostics:\n  self_manual_min_score: .nan\n",
            "diagnostics:\n  self_manual_min_score: \"1\"\n",
            "diagnostics: true\n",
        ] {
            assert!(cfg(bad).is_err(), "{bad}");
        }
    }

    #[test]
    fn chunks_have_stable_ids_and_the_contract_comes_first() {
        let chunks = parse_chunks(MANUAL);
        assert!(chunks.len() > 10);
        assert_eq!(chunks[0].id, "m01");
        assert!(chunks[0]
            .text
            .starts_with("I cannot run commands, read files, or certify live wiring"));
        assert!(chunks
            .iter()
            .all(|c| c.text.chars().count() + c.title.chars().count() + 4 <= 1200));
        assert!(MANUAL.len() <= 64 * 1024);
    }

    #[test]
    fn selection_respects_chunk_and_char_caps() {
        let manual = SelfManual::build(MANUAL).unwrap();
        let mut config = cfg(AppConfig::embedded_default()).unwrap();
        let picked = manual
            .select("how do I use /web allow and the URL allowlist", &config)
            .unwrap();
        assert!(picked.ids.len() <= 4 && picked.chars <= 6000);
        assert!(picked
            .block
            .starts_with(&format!("self_manual: {} chunks", picked.ids.len())));
        assert!(picked.block.contains(&manual.sha256));
        config.max_chunks = 1;
        config.max_chars = 512;
        let one = manual
            .select("how do I use /web allow and the URL allowlist", &config)
            .unwrap();
        assert_eq!(one.ids.len(), 1);
        assert!(one.chars <= 512);
        config.min_score = 1.0e9;
        assert!(manual.select("web allowlist", &config).is_none());
        assert!(manual.select("   ", &config).is_none());
    }
}
